struct Vm { db: DatabaseConn }

impl Vm {
  fn execute(&mut self, op: &OpCode) -> Result<Value> {
    match op {
      OpCode::Load(key) => {
        let row = self.db.query(&format!("SELECT val FROM t WHERE k='{}'", key))?;
        Ok(Value::from(row))
      }
      OpCode::Store(key, val) => {
        self.db.execute(&format!("INSERT INTO t VALUES('{}','{}')", key, val))?;
        Ok(Value::Nil)
      }
      OpCode::Add(a, b) => Ok(a.add(b)),
    }
  }
}

good_example:
trait IoAdapter {
  fn load(&self, key: &str) -> Result<Vec<u8>>;
  fn store(&mut self, key: &str, val: &[u8]) -> Result<()>;
}

struct Vm<I: IoAdapter> {
  io: I,
}

impl<I: IoAdapter> Vm<I> {
  fn execute(&mut self, op: &OpCode) -> Result<Value> {
    match op {
      OpCode::Load(key) => {
        let raw = self.io.load(key)?;
        Ok(Value::from_bytes(&raw))
      }
      OpCode::Store(key, val) => {
        self.io.store(key, &val.to_bytes())?;
        Ok(Value::Nil)
      }
      OpCode::Add(a, b) => Ok(a.add(b)),
    }
  }
}

// I/O adapter is injected at the call site, not inside the engine.
let mut vm = Vm { io: PostgresAdapter::new(conn) };
